UPDATE public.newsletters
SET html = regexp_replace(
  html,
  '<div style="margin:18px 0;">.*?</div>',
  $blk$<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:18px auto;"><tr><td width="28" height="28" align="center" valign="middle" style="width:28px;height:28px;border-radius:50%;background:#2b2b2b;text-align:center;vertical-align:middle;padding:0;"><a href="https://www.linkedin.com/company/sepri-group/" target="_blank" rel="noopener" style="display:block;line-height:0;text-decoration:none;"><img src="https://sepri-legis-digest.lovable.app/social/linkedin.png" width="14" height="14" alt="LinkedIn" style="display:inline-block;vertical-align:middle;border:0;" /></a></td><td width="8" style="width:8px;font-size:0;line-height:0;">&nbsp;</td><td width="28" height="28" align="center" valign="middle" style="width:28px;height:28px;border-radius:50%;background:#2b2b2b;text-align:center;vertical-align:middle;padding:0;"><a href="https://www.instagram.com/sepri_group/" target="_blank" rel="noopener" style="display:block;line-height:0;text-decoration:none;"><img src="https://sepri-legis-digest.lovable.app/social/instagram.png" width="14" height="14" alt="Instagram" style="display:inline-block;vertical-align:middle;border:0;" /></a></td><td width="8" style="width:8px;font-size:0;line-height:0;">&nbsp;</td><td width="28" height="28" align="center" valign="middle" style="width:28px;height:28px;border-radius:50%;background:#2b2b2b;text-align:center;vertical-align:middle;padding:0;"><a href="https://www.facebook.com/grupo.sepri" target="_blank" rel="noopener" style="display:block;line-height:0;text-decoration:none;"><img src="https://sepri-legis-digest.lovable.app/social/facebook.png" width="14" height="14" alt="Facebook" style="display:inline-block;vertical-align:middle;border:0;" /></a></td><td width="8" style="width:8px;font-size:0;line-height:0;">&nbsp;</td><td width="28" height="28" align="center" valign="middle" style="width:28px;height:28px;border-radius:50%;background:#2b2b2b;text-align:center;vertical-align:middle;padding:0;"><a href="https://www.youtube.com/@seprigroup" target="_blank" rel="noopener" style="display:block;line-height:0;text-decoration:none;"><img src="https://sepri-legis-digest.lovable.app/social/youtube.png" width="14" height="14" alt="YouTube" style="display:inline-block;vertical-align:middle;border:0;" /></a></td><td width="8" style="width:8px;font-size:0;line-height:0;">&nbsp;</td></tr></table>$blk$,
  'gs')
WHERE html LIKE '%margin:18px 0;%';